#!/usr/bin/env bash
#
# install.sh — fully self-contained installer for the DDoS Protection Dashboard.
#
# This single file contains everything: the Node.js app, the dashboard HTML,
# and the installer logic. Just upload/copy this ONE file to your Ubuntu/Debian
# server and run it — it creates the folder, writes every file, installs
# dependencies, hardens the kernel/firewall, sets up a systemd service so the
# dashboard is always online, and prints the final dashboard URL.
#
# Usage:
#   sudo bash install.sh
#
# What this script does:
#   1. Installs Node.js, build tools, ipset, and iptables-persistent
#   2. Creates /opt/ddos-protection and writes app.js, package.json, and the
#      dashboard HTML files into it (embedded below as base64 — nothing else
#      to upload)
#   3. Asks you for a dashboard admin username + password (set once, here)
#   4. Applies kernel/network hardening (SYN cookies, conntrack sizing, etc.)
#   5. Sets up ipset + a base iptables rule so blocking scales
#   6. Installs a systemd service so the dashboard survives reboots/crashes
#   7. Prints the final dashboard URL
#
# What this script does NOT do:
#   - It cannot stop large volumetric floods that saturate your network link
#     before they reach this box. For that you need an upstream provider
#     (Cloudflare Spectrum/Magic Transit, OVH/Voxility, your host's built-in
#     DDoS protection, etc.) in front of this server. This script hardens
#     everything that CAN be handled at the OS/application layer.
#
set -euo pipefail

# ---------- helpers ----------
c_green() { printf "\033[0;32m%s\033[0m\n" "$1"; }
c_yellow() { printf "\033[0;33m%s\033[0m\n" "$1"; }
c_red() { printf "\033[0;31m%s\033[0m\n" "$1"; }
c_blue() { printf "\033[0;34m%s\033[0m\n" "$1"; }

die() { c_red "ERROR: $1"; exit 1; }

if [ "$(id -u)" -ne 0 ]; then
    die "Please run this script as root (sudo bash install.sh)."
fi

if ! command -v apt-get >/dev/null 2>&1; then
    die "This script targets Ubuntu/Debian (apt-get not found)."
fi

INSTALL_DIR="/opt/ddos-protection"
SERVICE_NAME="ddos-protection"

echo ""
c_blue "======================================================"
c_blue "   DDoS Protection Dashboard — Installer"
c_blue "======================================================"
echo ""

# ---------- 1. Collect configuration up front ----------
read -rp "Dashboard port [3000]: " DASH_PORT
DASH_PORT=${DASH_PORT:-3000}

read -rp "Admin username [admin]: " ADMIN_USER
ADMIN_USER=${ADMIN_USER:-admin}

while true; do
    read -rsp "Admin password (min 8 chars): " ADMIN_PASSWORD
    echo ""
    if [ "${#ADMIN_PASSWORD}" -lt 8 ]; then
        c_yellow "Password must be at least 8 characters."
        continue
    fi
    read -rsp "Confirm password: " ADMIN_PASSWORD_CONFIRM
    echo ""
    if [ "$ADMIN_PASSWORD" != "$ADMIN_PASSWORD_CONFIRM" ]; then
        c_yellow "Passwords did not match, try again."
        continue
    fi
    break
done

read -rp "Comma-separated game server port(s) to protect [25565]: " GAME_PORTS
GAME_PORTS=${GAME_PORTS:-25565}

echo ""
c_yellow "Note: this only protects against connection/application-layer abuse."
c_yellow "For large volumetric floods you also need an upstream provider"
c_yellow "(Cloudflare Spectrum, OVH/Voxility, your host's DDoS protection, etc.)"
echo ""
read -rp "Press Enter to continue with installation..." _

# ---------- 2. System packages ----------
c_blue "==> Updating package lists..."
apt-get update -y

c_blue "==> Installing base packages (curl, build tools, ipset, iptables-persistent)..."
DEBIAN_FRONTEND=noninteractive apt-get install -y \
    curl ca-certificates gnupg build-essential python3 \
    ipset iptables netfilter-persistent iptables-persistent \
    ufw net-tools

if ! command -v node >/dev/null 2>&1 || [ "$(node -v | sed 's/v//;s/\..*//')" -lt 18 ]; then
    c_blue "==> Installing Node.js 20.x..."
    curl -fsSL https://deb.nodesource.com/setup_20.x | bash -
    apt-get install -y nodejs
else
    c_green "==> Node.js already installed: $(node -v)"
fi

# ---------- 3. Kernel / network hardening ----------
c_blue "==> Applying kernel-level DDoS hardening (sysctl)..."
SYSCTL_FILE="/etc/sysctl.d/99-ddos-protection.conf"
cat > "$SYSCTL_FILE" <<'SYSCTL_EOF'
# --- DDoS protection hardening (installed by ddos-protection installer) ---

# SYN flood protection
net.ipv4.tcp_syncookies = 1
net.ipv4.tcp_max_syn_backlog = 8192
net.ipv4.tcp_synack_retries = 2
net.ipv4.tcp_syn_retries = 3

# Larger connection tracking table so floods don't exhaust conntrack
net.netfilter.nf_conntrack_max = 262144
net.nf_conntrack_max = 262144

# Recycle TIME_WAIT sockets faster (mitigates TIME_WAIT exhaustion attacks)
net.ipv4.tcp_fin_timeout = 15
net.ipv4.tcp_tw_reuse = 1

# Ignore ICMP broadcast requests and bogus responses (Smurf-style attacks)
net.ipv4.icmp_echo_ignore_broadcasts = 1
net.ipv4.icmp_ignore_bogus_error_responses = 1

# Reverse path filtering (drop spoofed source IPs)
net.ipv4.conf.all.rp_filter = 1
net.ipv4.conf.default.rp_filter = 1

# Disable source routing and redirects (reduce spoofing/MITM surface)
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.all.send_redirects = 0

# Increase local port range and somaxconn for high connection churn (game servers)
net.ipv4.ip_local_port_range = 1024 65535
net.core.somaxconn = 4096
net.core.netdev_max_backlog = 5000
SYSCTL_EOF

modprobe nf_conntrack 2>/dev/null || true
sysctl -p "$SYSCTL_FILE" || c_yellow "Some sysctl keys may not apply on this kernel — continuing."

# ---------- 4. ipset + base iptables rule ----------
c_blue "==> Setting up ipset blocklist..."
ipset list ddos_blocklist >/dev/null 2>&1 || ipset create ddos_blocklist hash:ip timeout 0
iptables -C INPUT -m set --match-set ddos_blocklist src -j DROP 2>/dev/null || \
    iptables -I INPUT -m set --match-set ddos_blocklist src -j DROP

iptables -C INPUT -p tcp --syn -m limit --limit 200/s --limit-burst 400 -j ACCEPT 2>/dev/null || \
    iptables -I INPUT -p tcp --syn -m limit --limit 200/s --limit-burst 400 -j ACCEPT
iptables -C INPUT -p tcp --syn -j DROP 2>/dev/null || \
    iptables -A INPUT -p tcp --syn -j DROP

netfilter-persistent save || c_yellow "Could not persist iptables rules automatically — they will need reapplying after reboot unless netfilter-persistent is configured."

# ---------- 5. Firewall ports ----------
c_blue "==> Opening required ports in ufw (if active)..."
if command -v ufw >/dev/null 2>&1; then
    ufw allow "${DASH_PORT}/tcp" comment "DDoS dashboard" || true
    IFS=',' read -ra PORTS_ARR <<< "$GAME_PORTS"
    for p in "${PORTS_ARR[@]}"; do
        p_trimmed="$(echo "$p" | xargs)"
        [ -n "$p_trimmed" ] && ufw allow "${p_trimmed}" comment "Game server port" || true
    done
fi

# ---------- 6. Write application files (embedded in this script) ----------
c_blue "==> Creating ${INSTALL_DIR} and writing application files..."
mkdir -p "$INSTALL_DIR"

FILE_0_B64=""
FILE_1_B64=""
FILE_2_B64=""
FILE_3_B64=""
FILE_4_B64=""
FILE_5_B64=""
FILE_6_B64=""

write_embedded_files() {
    echo "$FILE_0_B64" | base64 -d > "${INSTALL_DIR}/app.js"
    echo "$FILE_1_B64" | base64 -d > "${INSTALL_DIR}/package.json"
    mkdir -p "${INSTALL_DIR}/public"
    echo "$FILE_2_B64" | base64 -d > "${INSTALL_DIR}/public/dashboard.html"
    mkdir -p "${INSTALL_DIR}/public"
    echo "$FILE_3_B64" | base64 -d > "${INSTALL_DIR}/public/login.html"
    mkdir -p "${INSTALL_DIR}/public"
    echo "$FILE_4_B64" | base64 -d > "${INSTALL_DIR}/public/settings.html"
    mkdir -p "${INSTALL_DIR}/public"
    echo "$FILE_5_B64" | base64 -d > "${INSTALL_DIR}/public/public.html"
    mkdir -p "${INSTALL_DIR}/public"
    echo "$FILE_6_B64" | base64 -d > "${INSTALL_DIR}/public/change-password.html"
}
write_embedded_files
c_green "==> Application files written."

cd "$INSTALL_DIR"

c_blue "==> Installing npm dependencies..."
npm install --omit=dev

# ---------- 7. Write .env with secrets ----------
c_blue "==> Writing environment configuration..."
JWT_SECRET="$(node -e "console.log(require('crypto').randomBytes(48).toString('hex'))")"

ENV_FILE="${INSTALL_DIR}/.env"
cat > "$ENV_FILE" <<ENV_EOF
PORT=${DASH_PORT}
ADMIN_USER=${ADMIN_USER}
ADMIN_PASSWORD=${ADMIN_PASSWORD}
ADMIN_RESET_PASSWORD=1
JWT_SECRET=${JWT_SECRET}
NODE_ENV=production
ENV_EOF
chmod 600 "$ENV_FILE"

# ---------- 8. Seed default settings (game ports, thresholds) ----------
c_blue "==> Configuring default game port(s): ${GAME_PORTS}"
cat > "${INSTALL_DIR}/.seed-settings.js" <<SEED_EOF
const Database = require("better-sqlite3");
const db = new Database("${INSTALL_DIR}/ddos.db");
db.exec(\`CREATE TABLE IF NOT EXISTS settings (
    id INTEGER PRIMARY KEY,
    rate_limit_per_minute INTEGER DEFAULT 60,
    max_bandwidth_per_minute INTEGER DEFAULT 1048576,
    auto_block INTEGER DEFAULT 1,
    block_duration INTEGER DEFAULT 3600,
    threat_threshold_medium INTEGER DEFAULT 100,
    threat_threshold_high INTEGER DEFAULT 500,
    threat_threshold_critical INTEGER DEFAULT 1000,
    auto_block_syn_recv INTEGER DEFAULT 50,
    auto_block_high_connections INTEGER DEFAULT 150,
    auto_block_port_scan INTEGER DEFAULT 10,
    auto_block_time_wait INTEGER DEFAULT 300,
    intelligent_blocking INTEGER DEFAULT 1,
    game_ports TEXT DEFAULT '25565',
    game_port_conn_threshold INTEGER DEFAULT 40,
    game_port_new_conn_threshold INTEGER DEFAULT 15,
    escalating_blocks INTEGER DEFAULT 1,
    max_block_duration INTEGER DEFAULT 86400
)\`);
db.prepare("INSERT OR IGNORE INTO settings (id) VALUES (1)").run();
db.prepare("UPDATE settings SET game_ports = ? WHERE id = 1").run("${GAME_PORTS}");
console.log("Settings seeded.");
SEED_EOF
node "${INSTALL_DIR}/.seed-settings.js"
rm -f "${INSTALL_DIR}/.seed-settings.js"

# ---------- 9. systemd service (always online) ----------
c_blue "==> Installing systemd service..."
SERVICE_FILE="/etc/systemd/system/${SERVICE_NAME}.service"
cat > "$SERVICE_FILE" <<SERVICE_EOF
[Unit]
Description=DDoS Protection Dashboard
After=network.target

[Service]
Type=simple
WorkingDirectory=${INSTALL_DIR}
EnvironmentFile=${INSTALL_DIR}/.env
ExecStart=$(command -v node) ${INSTALL_DIR}/app.js
Restart=always
RestartSec=3
User=root
# Needs root because it manages iptables/ipset. If you don't want the whole
# app running as root, use sudoers to grant a limited user passwordless
# access to just iptables/ipset/ss and change User= above.
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
SERVICE_EOF

systemctl daemon-reload
systemctl enable "$SERVICE_NAME"
systemctl restart "$SERVICE_NAME"

sleep 2

if systemctl is-active --quiet "$SERVICE_NAME"; then
    c_green "==> Service is running."
else
    c_red "==> Service failed to start. Check: journalctl -u ${SERVICE_NAME} -n 50"
    exit 1
fi

# ---------- 10. Final output ----------
SERVER_IP="$(curl -s -4 --max-time 5 https://ifconfig.me || hostname -I | awk '{print $1}')"

echo ""
c_green "======================================================"
c_green "   Installation complete!"
c_green "======================================================"
echo ""
echo "  Dashboard URL:   http://${SERVER_IP}:${DASH_PORT}"
echo "  Local URL:       http://localhost:${DASH_PORT}"
echo "  Admin username:  ${ADMIN_USER}"
echo "  Admin password:  (the one you just entered)"
echo ""
echo "  Service commands:"
echo "    systemctl status  ${SERVICE_NAME}"
echo "    systemctl restart ${SERVICE_NAME}"
echo "    journalctl -u     ${SERVICE_NAME} -f"
echo ""
c_yellow "  Reminder: this protects against connection/application-layer abuse"
c_yellow "  (SYN floods, connection floods, port scans, game-port abuse) at the"
c_yellow "  OS level. It cannot absorb a large bandwidth flood aimed at your"
c_yellow "  network link — put an upstream anti-DDoS provider in front of this"
c_yellow "  server (Cloudflare Spectrum, OVH/Voxility, or your host's own DDoS"
c_yellow "  protection) for that layer."
echo ""
